/**
 * Face-region brightness and left/right lighting balance. Side lighting casts
 * shadows that shift landmarks asymmetrically, so it is gated (SRS-QC-004).
 */
const SIZE = 32;
let ctx: CanvasRenderingContext2D | null = null;

function context(): CanvasRenderingContext2D | null {
  if (!ctx) {
    const c = document.createElement('canvas');
    c.width = SIZE;
    c.height = SIZE;
    ctx = c.getContext('2d', { willReadFrequently: true });
  }
  return ctx;
}

export function faceLuminance(
  src: CanvasImageSource,
  w: number,
  h: number,
  lm: ArrayLike<number>,
): { mean: number; asymmetry: number } | undefined {
  const c = context();
  if (!c || lm.length < 468 * 3) return undefined;
  let x0 = 1;
  let y0 = 1;
  let x1 = 0;
  let y1 = 0;
  for (let i = 0; i < 468; i++) {
    const x = lm[3 * i]!;
    const y = lm[3 * i + 1]!;
    if (x < x0) x0 = x;
    if (x > x1) x1 = x;
    if (y < y0) y0 = y;
    if (y > y1) y1 = y;
  }
  // Inner 70 % of the face box: skin only, little background.
  const mx = (x1 - x0) * 0.15;
  const my = (y1 - y0) * 0.15;
  const sx = Math.max(0, (x0 + mx) * w);
  const sy = Math.max(0, (y0 + my) * h);
  const sw = Math.min(w - sx, (x1 - x0 - 2 * mx) * w);
  const sh = Math.min(h - sy, (y1 - y0 - 2 * my) * h);
  if (sw < 4 || sh < 4) return undefined;
  c.drawImage(src, sx, sy, sw, sh, 0, 0, SIZE, SIZE);
  const d = c.getImageData(0, 0, SIZE, SIZE).data;
  const split = Math.round(((lm[3]! * w - sx) / sw) * SIZE); // nose tip (landmark 1) column
  let a = 0;
  let na = 0;
  let b = 0;
  let nb = 0;
  for (let y = 0; y < SIZE; y++)
    for (let x = 0; x < SIZE; x++) {
      const k = 4 * (y * SIZE + x);
      const l = 0.299 * d[k]! + 0.587 * d[k + 1]! + 0.114 * d[k + 2]!;
      if (x < split) {
        a += l;
        na++;
      } else {
        b += l;
        nb++;
      }
    }
  const la = na ? a / na : 0;
  const lb = nb ? b / nb : 0;
  return { mean: (a + b) / (na + nb), asymmetry: la + lb > 0 ? Math.abs(la - lb) / (la + lb) : 0 };
}
